$a = function ($path, $text) { return '<a href="/' . ltrim($path, '/') . '">' . $text . '</a>'; };

// [question, html answer, category slug]
$faqs = [
    ['What services does Yojo Solutions provide?',
        '<p>Yojo Solutions is a cybersecurity, audit and technology consulting organisation. Our work is organised into five divisions:</p><ul><li>' . $a('services/iso-audit-compliance', 'ISO Audit & Compliance') . ' — readiness, gap assessments and internal audits for ISO 27001, ISO 22301, ISO 42001, SOC 2, PCI DSS, GDPR and DPDPA.</li><li>' . $a('services/cybersecurity-audit', 'Cybersecurity Audit') . ' — web application, network, cloud, API and infrastructure security assessments, vulnerability assessment and penetration testing.</li><li>' . $a('services/cybersecurity-services', 'Cybersecurity Services') . ' — vulnerability management, architecture and configuration reviews, incident response advisory and security operations consulting.</li><li>' . $a('services/cyber-legal-services', 'Cyber Legal Services') . ' — technical documentation, evidence preservation and reporting guidance, delivered alongside your legal counsel.</li><li>' . $a('services/it-consulting', 'IT Consulting') . ' — infrastructure, IT governance, IT general and application controls and technology risk advisory.</li></ul><p>Most engagements combine more than one area — for example, a penetration test whose findings feed an ISO 27001 risk register.</p>', 'general'],
    ['What is an ISO 27001 audit?',
        '<p>ISO/IEC 27001 is the international standard for an <strong>Information Security Management System (ISMS)</strong> — a structured, risk-based way to protect information. An ISO 27001 audit checks whether the ISMS meets the standard\'s requirements and whether controls operate as described.</p><p>There are different kinds of audit:</p><ul><li><strong>Gap assessment</strong> — compares your current practices to the standard and lists what is missing.</li><li><strong>Internal audit</strong> — an independent check required by the standard before certification and annually after.</li><li><strong>Certification audit</strong> — performed by an accredited certification body, which alone issues the certificate.</li></ul><p>Typical focus areas include risk assessment and treatment, the Statement of Applicability, access control, supplier security, incident management and management review. See our ' . $a('services/iso-audit-compliance/iso-27001-consulting', 'ISO 27001 service') . '.</p>', 'iso-compliance'],
    ['What is the difference between a cybersecurity audit and penetration testing?',
        '<p>A <strong>cybersecurity audit</strong> is a broad evaluation of how well your policies, processes and technical controls protect the organisation. It reviews governance, access management, patching, backups, monitoring, vendor controls and more, usually through interviews, document review and evidence sampling.</p><p><strong>Penetration testing</strong> is a focused, authorised technical exercise in which testers attempt to identify and safely exploit weaknesses in specific systems — for example a web application or network — to show what an attacker could actually achieve.</p><p>An audit tells you whether the right controls exist and work; a penetration test shows whether specific systems can be broken into. Many organisations use both. See ' . $a('services/cybersecurity-audit/it-security-audit', 'IT Security Audit') . ' and ' . $a('services/cybersecurity-audit/penetration-testing', 'Penetration Testing') . '.</p>', 'cybersecurity-audits'],
    ['Why does an organization need a cybersecurity assessment?',
        '<p>A cybersecurity assessment gives you an objective picture of where you are exposed and how serious each issue is. It helps you:</p><ul><li><strong>Find weaknesses</strong> before attackers do — misconfigurations, unpatched systems, weak access controls.</li><li><strong>Understand business risk</strong> — which gaps could cause outages, data loss, fraud or regulatory penalties.</li><li><strong>Prioritise investment</strong> — spend on the fixes that reduce the most risk.</li><li><strong>Support decisions and evidence</strong> — for boards, customers, insurers and auditors.</li></ul><p>For example, a growing SaaS company might discover through an assessment that a single shared admin account controls its cloud environment — a high-impact issue that is quick to fix once known.</p>', 'cybersecurity-audits'],
    ['What is Vulnerability Assessment and Penetration Testing (VAPT)?',
        '<p>VAPT combines two complementary activities:</p><ul><li><strong>Vulnerability assessment</strong> — systematic discovery of known weaknesses using authenticated scanning and manual validation, producing a prioritised list.</li><li><strong>Penetration testing</strong> — expert-led, controlled attempts to exploit weaknesses and chain them together to demonstrate real impact.</li></ul><p>Every VAPT engagement starts with <strong>written authorisation</strong>, a defined scope, testing windows and rules of engagement. The output is a report with severity-rated findings, evidence, business impact and remediation guidance, followed by a retest to verify fixes. See ' . $a('services/cybersecurity-audit/vulnerability-assessment', 'Vulnerability Assessment') . '.</p>', 'cybersecurity-audits'],
    ['Does Yojo Solutions provide support for ISO compliance readiness?',
        '<p>Yes. Our readiness support typically includes:</p><ul><li><strong>Gap analysis</strong> against the standard\'s clauses and controls.</li><li><strong>Risk assessment</strong> and treatment planning with your control owners.</li><li><strong>Documentation support</strong> — policies, procedures, Statement of Applicability and records.</li><li><strong>Implementation guidance</strong> for technical and organisational controls.</li><li><strong>Internal audit</strong> and management review preparation.</li><li><strong>Support during the external audit</strong>, including responding to findings.</li></ul><p>We are a consulting organisation: formal certification is issued only by an independent, accredited certification body that you select. Keeping these roles separate protects the credibility of your certificate.</p>', 'iso-compliance'],
    ['How long does an audit or assessment take?',
        '<p>Timelines depend on several factors:</p><ul><li>The agreed <strong>scope</strong> — number of locations, business units or frameworks.</li><li><strong>Infrastructure size</strong> and number of applications, APIs or cloud accounts.</li><li>How quickly <strong>evidence and access</strong> can be provided.</li><li>Your current <strong>maturity</strong> and the availability of key staff.</li></ul><p>As a rough guide, a focused web application test may take one to two weeks including reporting, while a first-time ISO 27001 readiness programme often runs several months. We confirm a realistic timeline after the scoping discussion.</p>', 'engagement'],
    ['What information is required before beginning an audit?',
        '<p>Before an engagement starts we normally agree or request:</p><ul><li>The <strong>agreed scope</strong> — systems, locations, frameworks and exclusions.</li><li><strong>Organisation details</strong> — structure, key contacts and decision-makers.</li><li>Relevant <strong>policies and procedures</strong>.</li><li><strong>Architecture information</strong> — network diagrams, data flows and cloud accounts.</li><li>An <strong>asset inventory</strong> of in-scope systems and applications.</li><li><strong>Approved access arrangements</strong> — test accounts, VPN access, testing windows and written authorisation.</li></ul><p>Please do not send confidential evidence through public website forms; we agree a secure exchange method once the engagement is confirmed.</p>', 'engagement'],
    ['Do you provide cybersecurity services for startups and established enterprises?',
        '<p>Yes. The approach is tailored to size and maturity:</p><ul><li><strong>Startups</strong> usually need a pragmatic baseline — secure cloud setup, essential policies, a first penetration test and readiness for customer security questionnaires or SOC 2 / ISO 27001.</li><li><strong>Growing companies</strong> often need structured programmes — vulnerability management, access reviews, incident response plans and certification readiness.</li><li><strong>Established enterprises</strong> typically need independent assurance, regulatory compliance, specialist testing and governance reporting for boards.</li></ul><p>In every case we size recommendations to your team and budget rather than applying a one-size-fits-all checklist.</p>', 'cybersecurity-services'],
    ['What happens after a security audit?',
        '<p>An audit is the start of improvement, not the end. After fieldwork we:</p><ol><li><strong>Report</strong> — an executive summary and detailed findings with evidence and severity ratings.</li><li><strong>Prioritise</strong> — rank risks by likelihood, business impact and effort to fix.</li><li><strong>Recommend</strong> — practical remediation steps and, where needed, compensating controls.</li><li><strong>Walk through</strong> — explain findings to management and technical teams.</li><li><strong>Follow up</strong> — support remediation and, where agreed, perform a follow-up assessment or retest to confirm closure.</li></ol>', 'cybersecurity-audits'],
    ['Do you provide cyber legal services?',
        '<p>We provide the <strong>technical and documentation side</strong> of cyber-legal matters, including:</p><ul><li>Cyber incident documentation support.</li><li>Digital evidence preservation advisory.</li><li>Cybercrime reporting guidance.</li><li>Data privacy and regulatory guidance from an operational perspective.</li><li>Technical coordination with your legal counsel during incidents.</li></ul><p><strong>Important:</strong> Yojo Solutions is not a law firm. We do not provide legal advice, legal opinions or representation before courts, police or regulators. Legal advice must come from a qualified, enrolled advocate or your legal counsel; we work alongside them on technical matters. See ' . $a('services/cyber-legal-services', 'Cyber Legal Services') . '.</p>', 'cyber-legal'],
    ['How can an organization request a consultation?',
        '<p>You can ' . $a('book-consultation', 'book a consultation') . ' online, ' . $a('request-proposal', 'request a proposal') . ' or use the ' . $a('contact', 'contact form') . '. Please share:</p><ul><li>Your name, organisation and business email.</li><li>The services or frameworks you are interested in.</li><li>Your industry, approximate size and any deadlines (for example a customer or audit date).</li></ul><p>You will receive a reference number immediately. A consultant then reviews your request and contacts you to discuss scope, timelines and next steps — with no obligation.</p>', 'engagement'],
    ['What IT consulting services do you offer?',
        '<p>Our ' . $a('services/it-consulting', 'IT Consulting') . ' division covers infrastructure consulting, technology risk advisory, IT general controls (ITGC), IT application controls (ITAC), IT governance, technology process improvement and, where applicable, staff augmentation. These services help technology support business goals while satisfying auditors and regulators.</p>', 'it-consulting'],
    ['What are IT General Controls and why do auditors test them?',
        '<p>IT General Controls (ITGCs) are the foundational controls over access, change management, IT operations and backups that support reliable systems. Financial and compliance auditors test them because weak ITGCs undermine trust in every system and report that depends on them. We help you design, document and test ITGCs before your auditors arrive — see ' . $a('services/it-consulting/itgc', 'IT General Controls') . '.</p>', 'it-consulting'],
    ['Do you help with incident response planning?',
        '<p>Yes. Through ' . $a('services/cybersecurity-services/incident-response-advisory', 'Incident Response Advisory') . ' we help you build an incident response plan, scenario playbooks and communication paths, and then test them in facilitated tabletop exercises with leadership and technical teams.</p>', 'cybersecurity-services'],
];

